class Comment{final String id,mediaId,userId,content;final String? parentId,replyToUserId,username,displayName,avatarUrl;final int replyCount;final DateTime createdAt,updatedAt;Comment({required this.id,required this.mediaId,required this.userId,required this.content,this.parentId,this.replyToUserId,this.username,this.displayName,this.avatarUrl,this.replyCount=0,required this.createdAt,required this.updatedAt});bool get isReply=>parentId!=null;factory Comment.fromMap(Map<String,dynamic>m)=>Comment(id:m['id'] as String,mediaId:m['media_id'] as String,userId:m['user_id'] as String,content:m['content'] as String,parentId:m['parent_id'] as String?,replyToUserId:m['reply_to_user_id'] as String?,username:m['username'] as String?,displayName:m['display_name'] as String?,avatarUrl:m['avatar_url'] as String?,replyCount:(m['reply_count']??0) as int,createdAt:DateTime.parse(m['created_at'] as String).toUtc(),updatedAt:DateTime.parse(m['updated_at'] as String).toUtc());}
